def compact_nonzero(values):
    out = [0] * len(values)
    write = 0

    for read in range(len(values)):
        if values[read] != 0:
            # Store the kept value in the next free output position.
            out[{{write_index}}] = values[read]
            # Only a kept value consumes an output slot.
            {{advance}}

    return out[:write]

