def window_sums(values, k):
    total = sum(values[:k])
    out = [total]

    for right in range(k, len(values)):
        # Add the new value at the right edge.
        total += {{entering}}
        # Remove the value that was in the previous window but is no longer inside it.
        total -= {{leaving}}
        out.append(total)

    return out

